// =========================================================================
// PRODUCTION RESILIENT STORAGE PROXY (SAFELIFT 360 RESILIENCE ENGINE)
// =========================================================================
const safeStorage = (function() {
  const memoryCache = {};
  let storageSupported = true;

  try {
    const testKey = '__safelift_test__';
    window.localStorage.setItem(testKey, testKey);
    window.localStorage.removeItem(testKey);
  } catch (e) {
    storageSupported = false;
    console.warn('[SafeLift 360] LocalStorage restricted or private mode. Operating on resilient in-memory proxy.');
  }

  return {
    getItem: function(key) {
      if (storageSupported) {
        try {
          return window.localStorage.getItem(key);
        } catch (e) {
          return memoryCache[key] || null;
        }
      }
      return memoryCache[key] || null;
    },
    setItem: function(key, value) {
      const valStr = String(value);
      if (storageSupported) {
        try {
          window.localStorage.setItem(key, valStr);
          return;
        } catch (quotaError) {
          console.warn('[SafeLift 360] QuotaExceeded or restricted on key: ' + key + '. Storing in memory fallback.');
        }
      }
      memoryCache[key] = valStr;
    },
    removeItem: function(key) {
      if (storageSupported) {
        try {
          window.localStorage.removeItem(key);
        } catch (e) {}
      }
      delete memoryCache[key];
    },
    clear: function() {
      if (storageSupported) {
        try {
          window.localStorage.clear();
        } catch (e) {}
      }
      Object.keys(memoryCache).forEach(k => delete memoryCache[k]);
    },
    key: function(index) {
      if (storageSupported) {
        try {
          return window.localStorage.key(index);
        } catch (e) {
          return Object.keys(memoryCache)[index] || null;
        }
      }
      return Object.keys(memoryCache)[index] || null;
    },
    get length() {
      if (storageSupported) {
        try {
          return window.localStorage.length;
        } catch (e) {
          return Object.keys(memoryCache).length;
        }
      }
      return Object.keys(memoryCache).length;
    }
  };
})();

