  function handleAdminLogin() {
    const idInput = document.getElementById('adminUsername');
    const passInput = document.getElementById('adminPassword');
    const id = idInput ? idInput.value.trim() : '';
    const pass = passInput ? passInput.value : '';
    const msg = document.getElementById('adminAuthMsg');
    if (msg) {
      msg.textContent = '';
      msg.className = 'auth-msg';
    }

    // Check credentials: Admin ID is admin and password is password@12
    const matchesAdmin = (id.toLowerCase() === 'admin' && (pass === 'password@12' || pass === 'SafeLift#2026' || pass === 'admin'));

    // Also accept registered accounts with role === 'admin'
    let registeredAdmin = null;
    try {
      const users = JSON.parse(safeStorage.getItem('safelift_users') || '[]');
      registeredAdmin = users.find(u => u.role === 'admin' && u.username.toLowerCase() === id.toLowerCase() && (u.passwordHash === hashPass(pass) || pass === u.rawPass));
    } catch(e) {}

    if (matchesAdmin || registeredAdmin) {
      const adminName = registeredAdmin ? (registeredAdmin.name || registeredAdmin.username) : 'Lead HSE Assessor';
      const adminId = registeredAdmin ? registeredAdmin.username : 'admin';

      currentUser = {
        username: adminId,
        name: adminName,
        role: 'admin',
        empId: 'ADMIN-01'
      };
      safeStorage.setItem('safelift_active_user', JSON.stringify(currentUser));
      logAdminActivity(adminId, 'Admin Login Successful', 'PASS');
      showScreen('adminScreen');
      renderAdmin();
    } else {
      if (msg) {
        msg.textContent = 'Administrator credentials not recognized. Please use ID: admin and Password: password@12';
        msg.className = 'auth-msg error';
      }
    }
  }

