  function deleteWorker(uname) {
    if (!confirm(`Delete worker "${uname}" and their training history?`)) return;
    safeStorage.removeItem('safelift_user:' + uname);
    safeStorage.removeItem('safelift_stats:' + uname);
    renderAdmin();
  }

  function clearActivityLog() {
    if (!confirm('Clear all entries from the activity log?')) return;
    safeStorage.setItem('safelift_activity_log', '[]');
    renderAdmin();
  }

  function clearAllWorkerData() {
    if (!confirm('Delete ALL trainee training records? This action cannot be undone.')) return;
    for (let i = safeStorage.length - 1; i >= 0; i--) {
      const k = safeStorage.key(i);
      if (k && (k.startsWith('safelift_user:') || k.startsWith('safelift_stats:'))) {
        safeStorage.removeItem(k);
      }
    }
    renderAdmin();
  }

  /* ------------------- TOUCH CONTROLS (MOBILE & TABLET) ------------------- */
  function initTouchControls() {
    const container = document.getElementById("webgl-container");
    if (!container) return;

    let touchStartX = 0;
    let touchStartY = 0;
    let touchStartLon = 0;
    let touchStartLat = 0;
    let isTouching = false;

    container.addEventListener("touchstart", (e) => {
      if (e.touches.length === 1) {
        isTouching = true;
        touchStartX = e.touches[0].clientX;
        touchStartY = e.touches[0].clientY;
        touchStartLon = lon;
        touchStartLat = lat;
        dismissOnboarding();
      }
    }, { passive: true });

    container.addEventListener("touchmove", (e) => {
      if (isTouching && e.touches.length === 1) {
        const dx = e.touches[0].clientX - touchStartX;
        const dy = e.touches[0].clientY - touchStartY;
        lon = touchStartLon - dx * 0.25;
        lat = Math.max(-85, Math.min(85, touchStartLat + dy * 0.25));
        velLon = 0; velLat = 0;
      }
    }, { passive: true });

    container.addEventListener("touchend", () => {
      isTouching = false;
    }, { passive: true });
  }

