  /* =========================================================================
     2. SEAMLESS SPHERICAL THREE.JS PANORAMA (CLEAN VR, NO CLASHING 3D MESHES)
     ========================================================================= */
  const B64_WAREHOUSE = "data:image/jpeg;base64,";

  let scene, camera, renderer, sphereMesh;
  let isUserInteracting = false;
  let lastPointerX = 0, lastPointerY = 0;
  let lon = 45, lat = 0;
  let phi = 0, theta = 0;

  // Smoothing / Easing values for fluid rotation
  let currentLon = 45, currentLat = 0;
  let velLon = 0, velLat = 0;

  let totalScore = 0;
  let clearedScenarios = new Set();
  let currentScenarioIndex = null;
  let secondsElapsed = 0;
  let timerInterval = null;

  const container = document.getElementById("webgl-container");
  const overlay = document.getElementById("hotspotsOverlay");
  const hotspotObjects = [];

  function initThree() {
    scene = new THREE.Scene();
    camera = new THREE.PerspectiveCamera(70, window.innerWidth / window.innerHeight, 0.1, 1100);
    camera.target = new THREE.Vector3(0, 0, 0);

    // Continuous Inverted Sphere: eliminates all edge seams and distortion
    const geometry = new THREE.SphereGeometry(500, 60, 40);
    geometry.scale(-1, 1, 1);

    const loader = new THREE.TextureLoader();
    const texture = loader.load(B64_WAREHOUSE, () => {
      renderer.render(scene, camera);
    });
    texture.minFilter = THREE.LinearFilter;
    texture.generateMipmaps = false;

    const material = new THREE.MeshBasicMaterial({ map: texture });
    sphereMesh = new THREE.Mesh(geometry, material);
    scene.add(sphereMesh);

    renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    container.appendChild(renderer.domElement);

    // =========================================================================
    // WEBGL HARDWARE CONTEXT LOSS & AUTOMATIC RESTORATION LIFECYCLE
    // =========================================================================
    renderer.domElement.addEventListener('webglcontextlost', function(event) {
      event.preventDefault();
      console.warn('[SafeLift 360] WebGL Context Lost! Pausing animation frame rendering.');
      if (animId) cancelAnimationFrame(animId);
      notifyHud('⚠️ Hardware GPU suspended. Awaiting restoration...');
    }, false);

    renderer.domElement.addEventListener('webglcontextrestored', function(event) {
      console.info('[SafeLift 360] WebGL Context Restored! Rebinding textures and projection matrices.');
      initThree('canvasContainer');
      notifyHud('✅ 3D Warehouse Simulation Restored');
    }, false);


    // Event listeners
    container.addEventListener("pointerdown", onPointerDown);
    container.addEventListener("wheel", onDocumentWheel);
    window.addEventListener("resize", onWindowResize);

    initHotspotPositions();
    initKeyboardNavigation();
  }

