  function initHotspotPositions() {
    overlay.innerHTML = "";
    hotspotObjects.length = 0;

    SCENARIOS.forEach((sc, idx) => {
      const pPhi = THREE.MathUtils.degToRad(90 - sc.lat);
      const pTheta = THREE.MathUtils.degToRad(sc.lon);
      const r = 440; // Spatial anchor point

      const pos = new THREE.Vector3(
        r * Math.sin(pPhi) * Math.cos(pTheta),
        r * Math.cos(pPhi),
        r * Math.sin(pPhi) * Math.sin(pTheta)
      );

      const el = document.createElement("div");
      el.className = "hotspot-element";
      el.id = `hotspot-${idx}`;
      el.innerHTML = `
        <div class="hotspot-anchor-inner">
          <div class="hotspot-label-card">
            <span>${sc.title}</span>
            <span class="hotspot-weight-tag">${sc.weight}</span>
          </div>
          <div class="hotspot-beacon" id="beacon-${idx}">
            <div class="hotspot-inner-dot">
              <span class="beacon-check">&check;</span>
            </div>
          </div>
          <div class="hotspot-object-visual" id="object-visual-${idx}">
            ${renderRealisticSpatialObject(idx)}
            <div class="object-status-badge">&check; SECURED</div>
          </div>
          <div class="hotspot-floor-reticle"></div>
        </div>
      `;
      el.onclick = () => {
        dismissOnboarding();
        playSound('click');
        openScenarioModal(idx);
      };
      overlay.appendChild(el);

      hotspotObjects.push({
        element: el,
        position: pos,
        scenario: sc,
        index: idx
      });
    });
  }

  // KEYBOARD ACCESSIBILITY & PRESENTATION CONTROLS
  // KEYBOARD ACCESSIBILITY & PRESENTATION CONTROLS
  function initKeyboardNavigation() {
    window.addEventListener("keydown", (e) => {
      // Do not intercept keystrokes if the user is typing in any form input
      if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.tagName === 'SELECT')) {
        if (e.key === "Escape") {
          e.target.blur();
        }
        return;
      }

      // Only handle simulator hotkeys when simulatorScreen is active or when a modal is open
      if (currentScreen !== 'simulatorScreen' && !isAnyModalActive()) {
        return;
      }

      dismissOnboarding();

      // M toggles loads & equipment catalog menu
      if (e.key === 'm' || e.key === 'M') {
        e.preventDefault();
        toggleEquipmentMenu();
        return;
      }

      // H toggles 3D scene markers visibility
      if (e.key === 'h' || e.key === 'H') {
        e.preventDefault();
        toggleHotspotsVisibility();
        return;
      }

      // A toggles audio
      if (e.key === 'a' || e.key === 'A') {
        e.preventDefault();
        toggleAudio();
        return;
      }

      // F toggles fullscreen
      if (e.key === 'f' || e.key === 'F') {
        e.preventDefault();
        toggleFullscreen();
        return;
      }

      // Number keys 1-6 smoothly look at scenarios in 360 without forcing modal in front
      if (e.key >= '1' && e.key <= '6') {
        const idx = parseInt(e.key) - 1;
        if (idx < SCENARIOS.length) jumpToHotspot(idx, false);
        return;
      }

      // Keyboard arrow panning
      if (e.key === "ArrowLeft") {
        lon += 5;
      } else if (e.key === "ArrowRight") {
        lon -= 5;
      } else if (e.key === "ArrowUp") {
        lat = Math.min(85, lat + 4);
      } else if (e.key === "ArrowDown") {
        lat = Math.max(-85, lat - 4);
      }

      // Escape closes any active modal
      if (e.key === "Escape") {
        if (document.getElementById("equipmentMenuModal") && document.getElementById("equipmentMenuModal").classList.contains("active")) {
          closeEquipmentMenu();
          return;
        }
        if (document.getElementById("postureModal") && document.getElementById("postureModal").classList.contains("active")) {
          closePostureModal();
          return;
        }
        if (document.getElementById("debriefModal") && document.getElementById("debriefModal").classList.contains("active")) {
          closeDebriefModal();
          return;
        }
      }

      // Enter confirms active selection
      if ((e.key === "Enter" || e.key === " ") && document.getElementById("postureModal").classList.contains("active")) {
        const btn = document.getElementById("btnAdvanceModal");
        if (btn && btn.style.display !== "none") {
          advanceFromModal();
        }
      }
    });
  }

  function onPointerDown(event) {
    if (event.isPrimary === false) return;
    dismissOnboarding();
    isUserInteracting = true;
    lastPointerX = event.clientX;
    lastPointerY = event.clientY;
    velLon = 0; velLat = 0;

    document.addEventListener("pointermove", onPointerMove);
    document.addEventListener("pointerup", onPointerUp);
  }

  function onPointerMove(event) {
    if (event.isPrimary === false) return;
    const deltaX = event.clientX - lastPointerX;
    const deltaY = event.clientY - lastPointerY;
    lastPointerX = event.clientX;
    lastPointerY = event.clientY;

    lon -= deltaX * 0.16;
    lat += deltaY * 0.16;
    lat = Math.max(-85, Math.min(85, lat));

    // Weighted release momentum
    velLon = -deltaX * 0.08;
    velLat = deltaY * 0.08;
  }

  function onPointerUp(event) {
    if (event.isPrimary === false) return;
    isUserInteracting = false;
    document.removeEventListener("pointermove", onPointerMove);
    document.removeEventListener("pointerup", onPointerUp);
  }

  function onDocumentWheel(event) {
    dismissOnboarding();
    const fov = camera.fov + event.deltaY * 0.05;
    camera.fov = THREE.MathUtils.clamp(fov, 35, 85);
    camera.updateProjectionMatrix();
  }

  function onWindowResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  }

  // RENDER & PROJECT HOTSPOTS ONTO SCREEN
  function animate() {
    requestAnimationFrame(animate);

    if (!isUserInteracting) {
      lon += velLon;
      lat += velLat;
      velLon *= 0.90; // smooth damping
      velLat *= 0.90;
    }

    lat = Math.max(-85, Math.min(85, lat));
    
    // Smooth camera interpolation
    currentLon += (lon - currentLon) * 0.15;
    currentLat += (lat - currentLat) * 0.15;

    phi = THREE.MathUtils.degToRad(90 - currentLat);
    theta = THREE.MathUtils.degToRad(currentLon);

    camera.target.x = 500 * Math.sin(phi) * Math.cos(theta);
    camera.target.y = 500 * Math.cos(phi);
    camera.target.z = 500 * Math.sin(phi) * Math.sin(theta);

    camera.lookAt(camera.target);
    renderer.render(scene, camera);

    // Update bottom compass heading
    updateCompassDisplay(currentLon);

    // Project 3D Hotspots with Strict Backface Culling
    updateHotspotScreenCoordinates();
  }

  // STRICT BACKFACE CULLING CHECK AGAINST CAMERA FORWARD VECTOR
  let hotspotsVisible = true;

  function isAnyModalActive() {
    const p = document.getElementById("postureModal");
    const d = document.getElementById("debriefModal");
    const m = document.getElementById("equipmentMenuModal");
    return (p && p.classList.contains("active")) ||
           (d && d.classList.contains("active")) ||
           (m && m.classList.contains("active"));
  }

  function syncModalOpenState() {
    if (isAnyModalActive()) {
      document.body.classList.add("modal-open");
    } else {
      document.body.classList.remove("modal-open");
    }
  }

  // STRICT BACKFACE CULLING & TOTAL MODAL SUPPRESSION
  function updateHotspotScreenCoordinates() {
    // If any modal is active or markers are toggled off, suppress all 3D hotspots completely
    if (isAnyModalActive() || !hotspotsVisible) {
      hotspotObjects.forEach(h => {
        h.element.style.display = "none";
      });
      return;
    }

    const halfW = window.innerWidth * 0.5;
    const halfH = window.innerHeight * 0.5;
    const camDir = new THREE.Vector3();
    camera.getWorldDirection(camDir);

    hotspotObjects.forEach(h => {
      const toPoint = h.position.clone().normalize();
      const dot = camDir.dot(toPoint);

      // Must be within forward hemisphere of camera (dot > 0.15)
      if (dot > 0.15) {
        const p = h.position.clone();
        p.project(camera);

        if (p.z < 1) {
          const sx = (p.x * halfW) + halfW;
          const sy = (-(p.y * halfH)) + halfH;
          const fovScale = Math.max(0.75, Math.min(1.35, (70 / camera.fov)));
          h.element.style.display = "flex";
          h.element.style.left = `${sx}px`;
          h.element.style.top = `${sy}px`;
          h.element.style.transform = `translate(-50%, -68%) scale(${fovScale.toFixed(3)})`;
          return;
        }
      }
      h.element.style.display = "none";
    });
  }

  function updateCompassDisplay(camLon) {
    let normLon = ((camLon % 360) + 360) % 360;
    const degStr = Math.round(normLon).toString().padStart(3, "0") + "°";
    let cardinal = "N";
    if (normLon >= 22.5 && normLon < 67.5) cardinal = "NE";
    else if (normLon >= 67.5 && normLon < 112.5) cardinal = "E";
    else if (normLon >= 112.5 && normLon < 157.5) cardinal = "SE";
    else if (normLon >= 157.5 && normLon < 202.5) cardinal = "S";
    else if (normLon >= 202.5 && normLon < 247.5) cardinal = "SW";
    else if (normLon >= 247.5 && normLon < 292.5) cardinal = "W";
    else if (normLon >= 292.5 && normLon < 337.5) cardinal = "NW";
    document.getElementById("headingDegrees").innerText = `${degStr} ${cardinal}`;
  }

  // SHORTEST ANGULAR PATH INTERPOLATION (LOOKS AT TARGET WITHOUT FORCING MODAL IN FRONT)
  function jumpToHotspot(idx, autoOpen = false) {
    dismissOnboarding();
    playSound('click');
    const sc = SCENARIOS[idx];
    const diff = ((sc.lon - (lon % 360) + 540) % 360) - 180;
    lon += diff;
    lat = sc.lat;
    velLon = 0; velLat = 0;

    // Pulse target object in 360 view
    hotspotObjects.forEach((h, i) => {
      if (i === idx) {
        h.element.style.filter = "drop-shadow(0 0 24px rgba(245, 166, 35, 1)) brightness(1.2)";
        setTimeout(() => { if (h.element) h.element.style.filter = ""; }, 1800);
      }
    });

    if (autoOpen) {
      setTimeout(() => openScenarioModal(idx), 500);
    }
  }

  /* =========================================================================
     EQUIPMENT & LOADS CATALOG MENU SYSTEM
     ========================================================================= */
  function toggleEquipmentMenu() {
    playSound('click');
    const menu = document.getElementById("equipmentMenuModal");
    if (menu && menu.classList.contains("active")) {
      closeEquipmentMenu();
    } else {
      openEquipmentMenu();
    }
  }

  function openEquipmentMenu() {
    // Close other modals first so they never stack or overlap
    document.getElementById("postureModal").classList.remove("active");
    document.getElementById("debriefModal").classList.remove("active");

    renderEquipmentCatalogGrid();
    document.getElementById("equipmentMenuModal").classList.add("active");
    syncModalOpenState();
  }

  function closeEquipmentMenu() {
    playSound('click');
    document.getElementById("equipmentMenuModal").classList.remove("active");
    syncModalOpenState();
  }

  function renderEquipmentCatalogGrid() {
    const grid = document.getElementById("catalogGrid");
    if (!grid) return;
    grid.innerHTML = "";

    SCENARIOS.forEach((sc, i) => {
      const isCleared = clearedScenarios.has(i);
      const card = document.createElement("div");
      card.className = `catalog-card ${isCleared ? "cleared" : ""}`;
      card.innerHTML = `
        <div>
          <div class="catalog-card-header">
            <div class="catalog-card-title">${i + 1}. ${sc.title}</div>
            <div class="catalog-card-weight">${sc.weight}</div>
          </div>
          <div class="catalog-card-visual">
            ${renderRealisticSpatialObject(i)}
          </div>
          <div class="catalog-card-profile">${sc.compName}</div>
          <div class="catalog-card-specs">Mass: ${sc.compMass} &bull; Dim: ${sc.compDim}</div>
          <div class="catalog-card-directive"><strong>Directive:</strong> ${sc.compDirective}</div>
        </div>
        <div>
          <div style="font-size:10.5px; font-weight:700; margin-bottom:8px; color:${isCleared ? 'var(--green-safe)' : 'var(--amber-primary)'}">
            ${isCleared ? '&#10003; EVALUATION COMPLETED' : '&#9679; PENDING LIFT EVALUATION'}
          </div>
          <div class="catalog-card-actions">
            <button class="catalog-btn" onclick="lookAtScenarioIn360(${i})">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
              Look in 360°
            </button>
            <button class="catalog-btn primary" onclick="openScenarioFromMenu(${i})">
              Lift Assessment
            </button>
          </div>
        </div>
      `;
      grid.appendChild(card);
    });
  }

  function lookAtScenarioIn360(idx) {
    closeEquipmentMenu();
    closePostureModal();
    closeDebriefModal();
    jumpToHotspot(idx, false);
  }

  function openScenarioFromMenu(idx) {
    closeEquipmentMenu();
    openScenarioModal(idx);
  }

  function toggleHotspotsVisibility() {
    playSound('click');
    hotspotsVisible = !hotspotsVisible;
    const txt = document.getElementById("txtCatalogToggleMarkers");
    if (txt) {
      txt.innerText = hotspotsVisible ? "Hide 3D Markers from Scene" : "Show 3D Markers in Scene";
    }
    const btn = document.getElementById("btnCatalogToggleMarkers");
    if (btn) {
      btn.style.color = hotspotsVisible ? "var(--amber-primary)" : "var(--text-secondary)";
    }
    if (!hotspotsVisible) {
      hotspotObjects.forEach(h => h.element.style.display = "none");
    }
  }

  /* =========================================================================
     3. INTERACTIVE DECISION MODAL & REALISTIC COMPONENT INSPECTION
     ========================================================================= */
  let scenarioAttempts = {};

  /* =========================================================================
     SESSION PERSISTENCE (AUTO-SAVE & RECOVERY)
     ========================================================================= */
  function saveSessionState() {
    try {
      const data = {
        cleared: Array.from(clearedScenarios),
        totalScore: totalScore,
        secondsElapsed: secondsElapsed,
        scenarioAttempts: scenarioAttempts
      };
      safeStorage.setItem("safelift360_session", JSON.stringify(data));
    } catch(e) {}
  }

  function loadSessionState() {
    try {
      const saved = safeStorage.getItem("safelift360_session");
      if (saved) {
        const data = JSON.parse(saved);
        if (data && data.cleared && data.cleared.length > 0) {
          clearedScenarios = new Set(data.cleared);
          totalScore = data.totalScore || 0;
          secondsElapsed = data.secondsElapsed || 0;
          if (data.scenarioAttempts) scenarioAttempts = data.scenarioAttempts;
          
          updateHud();

          data.cleared.forEach(idx => {
            const h = document.getElementById(`hotspot-${idx}`);
            if (h) h.classList.add("done");
            const b = document.getElementById(`beacon-${idx}`);
            if (b) b.classList.add("done");
            const j = document.querySelectorAll(".jump-btn");
            if (j[idx]) j[idx].classList.add("completed");
          });

          const toast = document.getElementById("sessionToast");
          const msg = document.getElementById("sessionToastMsg");
          if (toast && msg) {
            msg.innerText = `Training Progress Restored: ${data.cleared.length}/6 Scenarios Cleared • ${totalScore} PTS`;
            toast.style.display = "flex";
            setTimeout(() => { toast.style.display = "none"; }, 4000);
          }
        }
      }
    } catch(e) {}
  }

  function printComplianceCertificate() {
    playSound('click');
    document.body.classList.add('printing-certificate');
    // Ensure trainee name is set
    const nameInput = document.getElementById("certTraineeName");
    if (nameInput && !nameInput.value && currentUser) {
      nameInput.value = currentUser.name || currentUser.username;
    }
    window.print();
    setTimeout(() => {
      document.body.classList.remove('printing-certificate');
    }, 1500);
  }

  /* =========================================================================
     3. INTERACTIVE DECISION MODAL & REALISTIC COMPONENT INSPECTION
     ========================================================================= */
  function openScenarioModal(idx) {
    // Close debrief and menu so they never overlap
    document.getElementById("debriefModal").classList.remove("active");
    const m = document.getElementById("equipmentMenuModal");
    if (m) m.classList.remove("active");

    currentScenarioIndex = idx;
    const sc = SCENARIOS[idx];
    
    // Initialize attempts for this scenario
    if (scenarioAttempts[idx] === undefined) {
      scenarioAttempts[idx] = 0;
    }

    document.getElementById("modalTitle").innerText = `${idx + 1}. ${sc.title}`;
    document.getElementById("modalHseTag").innerText = sc.hseTag;
    document.getElementById("modalWeightTag").innerText = sc.weight;
    document.getElementById("modalDescription").innerText = sc.description;

    // INJECT REALISTIC EQUIPMENT GRAPHIC & PHYSICAL SPECS
    document.getElementById("equipmentRenderBox").innerHTML = REALISTIC_SVGS[idx];
    document.getElementById("equipmentName").innerText = sc.compName;
    document.getElementById("specMass").innerText = sc.compMass;
    document.getElementById("specDim").innerText = sc.compDim;
    document.getElementById("specCog").innerText = sc.compCog;
    document.getElementById("specDirective").innerText = sc.compDirective;

    // Clear previous clinical risk alert box
    const riskBox = document.getElementById("clinicalRiskBox");
    if (riskBox) riskBox.style.display = "none";

    const cardsContainer = document.getElementById("choiceCardsContainer");
    cardsContainer.innerHTML = "";

    sc.choices.forEach((ch, cIdx) => {
      const card = document.createElement("div");
      card.className = "choice-card";
      card.innerHTML = `
        <div>
          <div class="choice-tag">TECHNIQUE 0${cIdx + 1}</div>
          <div class="choice-name">${ch.name}</div>
          <div class="choice-desc">${ch.desc}</div>
        </div>
      `;
      card.onclick = () => selectChoice(cIdx);
      cardsContainer.appendChild(card);
    });

    updateSpineGauge(85, "Select a lifting technique above to evaluate real-time spinal forces.", "#30d158");
    document.getElementById("btnAdvanceModal").style.display = "none";
    document.getElementById("postureModal").classList.add("active");
    syncModalOpenState();
  }

  function selectChoice(cIdx) {
    const sc = SCENARIOS[currentScenarioIndex];
    const choice = sc.choices[cIdx];
    
    // Track attempts for this scenario
    scenarioAttempts[currentScenarioIndex] = (scenarioAttempts[currentScenarioIndex] || 0) + 1;
    const attempts = scenarioAttempts[currentScenarioIndex];

    const cards = document.querySelectorAll(".choice-card");
    cards.forEach((c, i) => {
      c.className = "choice-card";
      if (i === cIdx) {
        c.classList.add(choice.isCorrect ? "selected-safe" : "selected-danger");
      }
    });

    if (choice.isCorrect) {
      playSound('safe');
    } else {
      playSound('danger');
    }

    updateSpineGauge(choice.loadKg, choice.explanation, choice.statusColor);

    // Update Clinical Anatomical Risk Alert Callout
    const riskBox = document.getElementById("clinicalRiskBox");
    if (riskBox) {
      riskBox.style.display = "flex";
      if (choice.isCorrect) {
        const earnedPts = attempts === 1 ? 100 : (attempts === 2 ? 50 : 25);
        const masteryTag = attempts === 1 ? "1st-Attempt Mastery" : (attempts === 2 ? "Remediated (2nd Try)" : "Guided Completion");
        riskBox.className = "clinical-risk-box safe";
        riskBox.innerHTML = `
          <div class="risk-icon">&#10003;</div>
          <div>
            <div class="risk-title">HSE COMPLIANCE CONFIRMED (+${earnedPts} PTS &bull; ${masteryTag})</div>
            <div>${choice.explanation}</div>
            <div style="font-size:11px; font-weight:700; color:var(--green-safe); margin-top:4px;">Optimal Spinal Lordosis: Workload transferred directly to quadriceps and glutes. Spine safely within 2,000 N functional limit.</div>
          </div>
        `;
      } else {
        const isNioshExceeded = choice.loadKg >= 340;
        riskBox.className = "clinical-risk-box hazard";
        riskBox.innerHTML = `
          <div class="risk-icon">&#9888;</div>
          <div>
            <div class="risk-title">BIOMECHANICAL HAZARD DETECTED (${choice.loadKg} KG / ${Math.round(choice.loadKg * 9.81)} N COMPRESSION)</div>
            <div>${choice.explanation}</div>
            <div class="risk-threshold-warning">${isNioshExceeded ? '&#9888; CRITICAL: Exceeds NIOSH 3,400 N Maximum Action Limit. Acute risk of L5/S1 vertebral disc herniation.' : '&#9888; CAUTION: Exceeds recommended 2,000 N ergonomic limit. Elevated musculoskeletal fatigue.'}</div>
          </div>
        `;
      }
    }

    const advanceBtn = document.getElementById("btnAdvanceModal");
    if (choice.isCorrect) {
      advanceBtn.style.display = "block";
      advanceBtn.innerText = "Confirm & Clear Hotspot [Enter]";

      if (!clearedScenarios.has(currentScenarioIndex)) {
        clearedScenarios.add(currentScenarioIndex);
        
        // Weighted scoring based on attempts
        const earnedPts = attempts === 1 ? 100 : (attempts === 2 ? 50 : 25);
        totalScore += earnedPts;
        updateHud();
        saveSessionState();

        document.getElementById(`hotspot-${currentScenarioIndex}`).classList.add("done");
        document.getElementById(`beacon-${currentScenarioIndex}`).classList.add("done");
        const jumpBtns = document.querySelectorAll(".jump-btn");
        if (jumpBtns[currentScenarioIndex]) jumpBtns[currentScenarioIndex].classList.add("completed");
      }
    } else {
      advanceBtn.style.display = "none";
    }
  }

  function updateSpineGauge(loadKg, text, color) {
    document.getElementById("biomechLoadVal").innerText = `${loadKg} kg`;
    document.getElementById("biomechLoadVal").style.color = color;
    document.getElementById("biomechExplanation").innerText = text;

    const badge = document.getElementById("spineNioshStatusBadge");
    if (badge) {
      if (loadKg <= 200) {
        badge.innerText = "SAFE ERGONOMIC ZONE";
        badge.style.color = "var(--green-safe)";
        badge.style.background = "rgba(48, 209, 88, 0.2)";
      } else if (loadKg <= 340) {
        badge.innerText = "CAUTION: ELEVATED SHEAR";
        badge.style.color = "var(--amber-primary)";
        badge.style.background = "rgba(245, 166, 35, 0.2)";
      } else {
        badge.innerText = "CRITICAL: NIOSH ACTION LIMIT EXCEEDED";
        badge.style.color = "var(--red-danger)";
        badge.style.background = "rgba(255, 69, 58, 0.2)";
      }
    }

    const isRed = (color === "#ff453a");
    const isAmber = (color === "#ff9f0a");
    const fill = isRed ? "#ff453a" : (isAmber ? "#ff9f0a" : "#30d158");

    document.getElementById("spineL5S1").setAttribute("fill", fill);
    document.getElementById("spineLumbar").setAttribute("fill", isRed ? "#ff453a" : "#30d158");
  }

  function closePostureModal() {
    playSound('click');
    document.getElementById("postureModal").classList.remove("active");
    syncModalOpenState();
  }

  function advanceFromModal() {
    playSound('click');
    closePostureModal();
    if (clearedScenarios.size === SCENARIOS.length) {
      setTimeout(showDebriefModal, 450);
    }
  }

  function updateHud() {
    document.getElementById("hudClearedCount").innerText = `${clearedScenarios.size} / ${SCENARIOS.length}`;
    document.getElementById("hudScoreBadge").innerText = `${totalScore} PTS`;
  }

  /* =========================================================================
     4. TIMEKEEPING & AUDIT DEBRIEF
     ========================================================================= */
  function startSessionTimer() {
    timerInterval = setInterval(() => {
      secondsElapsed++;
      const m = Math.floor(secondsElapsed / 60).toString().padStart(2, "0");
      const s = (secondsElapsed % 60).toString().padStart(2, "0");
      document.getElementById("hudTimer").innerText = `${m}:${s}`;
      if (secondsElapsed % 10 === 0) saveSessionState();
    }, 1000);
  }

  function showDebriefModal() {
    // Record attempt for current trainee
    if (currentUser) {
      const statsKey = 'safelift_stats:' + currentUser.username;
      const raw = safeStorage.getItem(statsKey);
      const s = raw ? JSON.parse(raw) : { logins: 1, attempts: 0, totalMs: 0, bestScore: 0 };
      s.attempts = (s.attempts || 0) + 1;
      s.totalMs = (s.totalMs || 0) + (secondsElapsed * 1000);
      s.bestScore = Math.max(s.bestScore || 0, totalScore);
      safeStorage.setItem(statsKey, JSON.stringify(s));
      logAdminActivity(currentUser.username, 'Simulation Completed (6 Scenarios)', totalScore >= 400 ? 'PASS' : 'FAIL');
    }

    playSound('safe');
    // Close posture and menu so they NEVER overlap
    document.getElementById("postureModal").classList.remove("active");
    const m = document.getElementById("equipmentMenuModal");
    if (m) m.classList.remove("active");

    const mm = Math.floor(secondsElapsed / 60).toString().padStart(2, "0");
    const ss = (secondsElapsed % 60).toString().padStart(2, "0");
    document.getElementById("debriefTime").innerText = `${mm}:${ss}`;
    document.getElementById("debriefFinalScore").innerText = `${totalScore} PTS`;
    const now = new Date();
    const dateStr = now.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
    const dispDate = document.getElementById("certDisplayDate");
    const issueDate = document.getElementById("certIssueDate");
    if (dispDate) dispDate.textContent = dateStr;
    if (issueDate) issueDate.textContent = dateStr;
    if (currentUser) {
      const nameInput = document.getElementById("certTraineeName");
      if (nameInput) nameInput.value = currentUser.name || currentUser.username;
      const empInput = document.getElementById("certEmployeeId");
      if (empInput && currentUser.empId) empInput.value = currentUser.empId;
      const signEl = document.getElementById("certTraineeSign");
      if (signEl) signEl.textContent = currentUser.name || currentUser.username;
    }
    document.getElementById("debriefReadiness").innerText = `${Math.round((clearedScenarios.size / SCENARIOS.length) * 100)}%`;

    const list = document.getElementById("debriefChecklist");
    list.innerHTML = "";
    SCENARIOS.forEach((sc, i) => {
      const attempts = scenarioAttempts[i] || 1;
      const tierBadge = attempts === 1 ? 'Mastery (100 Pts)' : (attempts === 2 ? 'Remediated (50 Pts)' : 'Guided (25 Pts)');
      const li = document.createElement("li");
      li.innerHTML = `
        <span><strong>${i + 1}. ${sc.title}</strong> &bull; ${sc.weight} (${sc.compName})</span>
        <span style="color:var(--green-safe); font-weight:700;">&check; ${tierBadge}</span>
      `;
      list.appendChild(li);
    });

    document.getElementById("debriefModal").classList.add("active");
    syncModalOpenState();
    saveSessionState();
  }

  function closeDebriefModal() {
    playSound('click');
    document.getElementById("debriefModal").classList.remove("active");
    syncModalOpenState();
  }

  function resetSimulation() {
    playSound('click');
    try {
      safeStorage.removeItem("safelift360_session");
    } catch(e) {}
    clearedScenarios.clear();
    scenarioAttempts = {};
    totalScore = 0;
    secondsElapsed = 0;
    updateHud();
    document.querySelectorAll(".jump-btn").forEach(b => b.classList.remove("completed"));
    document.querySelectorAll(".hotspot-element").forEach(b => b.classList.remove("done"));
    document.querySelectorAll(".hotspot-beacon").forEach(b => b.classList.remove("done"));
    document.getElementById("debriefModal").classList.remove("active");
    document.getElementById("postureModal").classList.remove("active");
    const menu = document.getElementById("equipmentMenuModal");
    if (menu) menu.classList.remove("active");
    syncModalOpenState();
    lon = 45; lat = 0;
    renderTraineeDashboard();
  }
  // START APPLICATION
  window.onload = () => {
    initTouchControls();
    const nameInput = document.getElementById("certTraineeName");
    if (nameInput) {
      nameInput.addEventListener("input", (e) => {
        const signEl = document.getElementById("certTraineeSign");
        if (signEl) signEl.textContent = e.target.value.trim() || (currentUser && (currentUser.name || currentUser.username)) || "Trainee Signature";
      });
    }
    // Check if an existing logged in user session is stored
    const savedUser = safeStorage.getItem('safelift_active_user');
    if (savedUser) {
      try {
        currentUser = JSON.parse(savedUser);
        if (currentUser.role === 'admin') {
          showScreen('adminScreen');
          renderAdmin();
        } else {
          goToDashboard();
        }
      } catch(e) {
        goToLanding();
      }
    } else {
      goToLanding();
    }
  };



