// 1. Input Sanitization
if (typeof sanitizeInput === 'undefined') {
  function sanitizeInput(str) {
    if (!str) return '';
    const div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }
}

// 2. Mobile Touch Event Listeners for 360 Canvas Orbit
(function initTouchOrbitPatch() {
  let touchStartX = 0;
  let touchStartY = 0;
  let touchTracking = false;

  function bindTouch() {
    const canvasContainer = document.getElementById('webgl-container') || document.getElementById('viewport') || document.body;
    if (!canvasContainer) return;

    canvasContainer.addEventListener('touchstart', function(e) {
      if (e.touches.length === 1) {
        touchStartX = e.touches[0].clientX;
        touchStartY = e.touches[0].clientY;
        touchTracking = true;
      }
    }, { passive: true });

    canvasContainer.addEventListener('touchmove', function(e) {
      if (!touchTracking || e.touches.length !== 1) return;
      
      const deltaX = e.touches[0].clientX - touchStartX;
      const deltaY = e.touches[0].clientY - touchStartY;
      
      touchStartX = e.touches[0].clientX;
      touchStartY = e.touches[0].clientY;
      
      // Map movement to longitude (lon) and latitude (lat)
      if (typeof lon !== 'undefined' && typeof lat !== 'undefined') {
        lon -= deltaX * 0.18;
        lat += deltaY * 0.18;
        lat = Math.max(-85, Math.min(85, lat));
      }
    }, { passive: true });

    canvasContainer.addEventListener('touchend', function() {
      touchTracking = false;
    }, { passive: true });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bindTouch);
  } else {
    bindTouch();
  }
})();

