// --- 1. SECURE INPUT SANITIZATION UTILITY ---
function sanitizeText(input) {
  if (typeof input !== 'string') return '';
  const map = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#x27;',
    "/": '&#x2F;'
  };
  return input.replace(/[&<>"'/]/g, function(char) {
    return map[char];
  });
}

// --- 2. MULTI-TOUCH / TABLET ORBIT ENGINE ---
